"""Independent check of Task 1's claim: for three binary views generated by a 2-state latent
("model A"), a 3-state latent reproduces P(Y) exactly with *less* information I(X;Y).
Own implementation (no shared code with Task 1)."""
import itertools

import numpy as np
from scipy.optimize import minimize
from scipy.special import expit, softmax


def joint(pi, P):
    """p(x, y) with P[i, x] = P(Y_i = 1 | x); columns of the result index y in {0,1}^n."""
    ys = np.array(list(itertools.product([0, 1], repeat=P.shape[0])))
    lik = np.prod(np.where(ys[None] == 1, P.T[:, None, :], 1 - P.T[:, None, :]), axis=2)
    return pi[:, None] * lik


def mutual_info(pxy):
    px, py = pxy.sum(1, keepdims=True), pxy.sum(0, keepdims=True)
    m = (pxy > 0) & (px * py > 0)
    return float((pxy[m] * np.log2(pxy[m] / (px * py)[m])).sum())


pi_true = np.array([.122, .878])
P_true = np.array([[.104, .985], [.264, .102], [.675, .48]])
py = joint(pi_true, P_true).sum(0)
k = 3
unpack = lambda z: (softmax(z[:k]), expit(np.clip(z[k:], -30, 30)).reshape(3, k))
fit = {"type": "eq", "fun": lambda z: (joint(*unpack(z)).sum(0) - py)[1:]}
rng, best = np.random.default_rng(0), None
for _ in range(60):
    r = minimize(lambda z: mutual_info(joint(*unpack(z))), rng.normal(0, 2, k + 3 * k), method="SLSQP",
                 constraints=[fit], options=dict(maxiter=3000, ftol=1e-14))
    viol = np.abs(joint(*unpack(r.x)).sum(0) - py).max()
    if viol < 1e-10 and (best is None or r.fun < best[0]):
        best = (r.fun, viol, *unpack(r.x))
print(f"true 2-state latent: I(X;Y) = {mutual_info(joint(pi_true, P_true)):.4f} bits")
print(f"3-state exact fit:   I(X;Y) = {best[0]:.4f} bits (max |P(y) error| {best[1]:.1e})")
print("pi =", best[2].round(4), "\nP(Y_i=1|x) =\n", best[3].round(4))
